import React, { useEffect, useState } from "react";
import styled from "styled-components";
import TabBar from "../../components/common/TabBar";
import ProfileHeader from "../../components/common/ProfileHeader";
import LoyaltyTile from "../../components/common/LoyaltyTile";
import TextBox from "../../components/common/TextBox";
import Button from "../../components/common/Button";

/* ---- Styled Wrappers ---- */
const PageWrapper = styled.div`
  background-color: ${({ theme }) => theme.colors.background};
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContentWrapper = styled.div`
  width: 90%;
  max-width: 1200px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding: 60px 0;
`;

const Card = styled.div`
  background: #fff;
  border-radius: 16px;
  padding: 32px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
`;

const SectionTitle = styled.h2`
  font-size: 20px;
  font-weight: 700;
  color: #2d2d2d;
  margin-bottom: 20px;
`;

const HeaderRow = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
`;

const LoyaltyList = styled.div`
  display: flex;
  flex-direction: column;
  gap: 16px;
`;

const ProfilePage: React.FC = () => {
  const [isEditing, setIsEditing] = useState(false);
  const [user, setUser] = useState<any>(null);

  // Load user information
  useEffect(() => {
    // Load from localStorage for instant display
    const stored = localStorage.getItem("customer");
    if (stored) {
      const data = JSON.parse(stored);
      setUser({
        name: `${data.firstName} ${data.lastName}`,
        email: data.email,
        bookings: 0,
        visited: 0,
        loyaltyPrograms: 0,
        loyalty: []
      });
    }

    // Fetch latest from backend
    const token = localStorage.getItem("customerToken");
    if (token) {
      fetch("http://localhost:5000/api/customers/me", {
        headers: { Authorization: `Bearer ${token}` }
      })
        .then((res) => res.json())
        .then((data) => {
          setUser({
            name: `${data.firstName} ${data.lastName}`,
            email: data.email,
            bookings: 0,          // keep UI value only; real stats coming later
            visited: 0,
            loyaltyPrograms: 0,
            loyalty: []
          });
          localStorage.setItem("customer", JSON.stringify(data));
        })
        .catch(() => {});
    }
  }, []);

  if (!user) return <div style={{ padding: 40 }}>Loading...</div>;

  return (
    <PageWrapper>
      <TabBar type="customer" />

      <ContentWrapper>
        {/* ---------- Profile Header ---------- */}
        <ProfileHeader
          type="customer"
          name={user.name}
          stat1={user.bookings}
          stat2={user.visited}
          stat3={user.loyaltyPrograms}
        />

        {/* ---------- Personal Information ---------- */}
        <Card>
          <HeaderRow>
            <SectionTitle>Personal Information</SectionTitle>
            <Button
              onClick={() => setIsEditing(!isEditing)}
              style={{
                padding: "8px 16px",
                fontSize: "14px",
                borderRadius: "8px",
                width: "auto",
              }}
            >
              {isEditing ? "Save" : "Edit"}
            </Button>
          </HeaderRow>

          <div
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr",
              gap: "16px",
            }}
          >
            <TextBox
              label="Name"
              value={user.name}
              readOnly={!isEditing}
              onChange={() => {}}
            />

            {/* PHONE REMOVED */}

            <div style={{ gridColumn: "1 / span 2" }}>
              <TextBox
                label="Email"
                value={user.email}
                readOnly={!isEditing}
                onChange={() => {}}
                style={{ width: "100%" }}
              />
            </div>
          </div>
        </Card>

        {/* ---------- Loyalty Programs (KEEP UI ONLY) ---------- */}
        <Card>
          <SectionTitle>My Loyalty Programs</SectionTitle>
          <LoyaltyList>
            {user.loyalty.length === 0 ? (
              <div style={{ color: "#999" }}>No loyalty programs yet.</div>
            ) : (
              user.loyalty.map((item: any) => (
                <LoyaltyTile key={item.id} {...item} />
              ))
            )}
          </LoyaltyList>
        </Card>
      </ContentWrapper>
    </PageWrapper>
  );
};

export default ProfilePage;
